import React,{useEffect,useState} from 'react';import{Building2,Users,FileText,Receipt,LayoutDashboard,LogOut,Search,ChartNoAxesCombined,MessageCircle,Download,CalendarClock,Wallet,ShieldCheck}from'lucide-react';
const ALP_REPORT_LOGO='data:image/jpeg;base64,';
const API=(import.meta.env.VITE_API_URL||'http://localhost:3001/api').replace(/\/$/,'');const money=n=>(Number(n||0)/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});const date=d=>d?new Date(d).toLocaleDateString('pt-BR',{timeZone:'UTC'}):'-';const cents=v=>Math.round(Number(v||0)*100);
async function request(path,method='GET',body,token){const headers={};if(token)headers.Authorization=`Bearer ${token}`;if(body!==undefined&&!(body instanceof FormData))headers['Content-Type']='application/json';const r=await fetch(API+path,{method,headers,body:body===undefined?undefined:body instanceof FormData?body:JSON.stringify(body)});const data=await r.json().catch(()=>({}));if(!r.ok)throw Error(data.error||`Erro ${r.status}`);return data}
const field=(label,value,onChange,type='text',props={})=><label className="field"><span>{label}</span><input type={type} value={value??''} onChange={e=>onChange(e.target.value)} {...props}/></label>;
const emptyClient={name:'',cpf:'',password:'',phone:'',email:'',rg:'',birthDate:'',sex:'',maritalStatus:'',spouseName:'',spouseCpf:''};const emptyProperty={reference:'',address:'',notes:'',stateCode:'',cityCode:'',city:'',financed:false};const emptyContract={clientId:'',propertyId:'',propertyPrice:'',financedAmount:'0',installmentCount:'12',startDate:new Date().toISOString().slice(0,10),interestType:'NONE',monthlyRate:'0'};
export default function App(){const[token,setToken]=useState(sessionStorage.getItem('gi-token')||'');const[user,setUser]=useState(null);const[login,setLogin]=useState({cpf:'',password:''});const[page,setPage]=useState('Início');const[clients,setClients]=useState([]),[properties,setProperties]=useState([]),[contracts,setContracts]=useState([]),[receipts,setReceipts]=useState([]),[mine,setMine]=useState([]);const[cf,setCf]=useState(emptyClient),[pf,setPf]=useState(emptyProperty),[kf,setKf]=useState(emptyContract);const[pix,setPix]=useState(null),[modal,setModal]=useState(null),[profile,setProfile]=useState(null),[pw,setPw]=useState({currentPassword:"",newPassword:""}),[calendarMonth,setCalendarMonth]=useState(new Date().toISOString().slice(0,7));const[billTab,setBillTab]=useState('open'),[billDetail,setBillDetail]=useState(null),[showInstallmentReport,setShowInstallmentReport]=useState(false);const[editingClient,setEditingClient]=useState(null),[editingProperty,setEditingProperty]=useState(null),[editingContract,setEditingContract]=useState(null),[selected,setSelected]=useState(null),[search,setSearch]=useState(''),[message,setMessage]=useState(''),[loading,setLoading]=useState(false);
const update=(setter,key,val)=>setter(p=>({...p,[key]:val}));const notify=(v)=>{setMessage(v);window.scrollTo({top:0,behavior:'smooth'})};
const refresh=async(t=token,role=user?.role)=>{if(!t)return;try{if(role==='ADMIN'){const [c,p,k,r]=await Promise.all(['/clients','/properties','/contracts','/receipts'].map(s=>request(s,'GET',undefined,t)));setClients(c);setProperties(p);setContracts(k);setReceipts(r)}else setMine(await request('/my/contracts','GET',undefined,t))}catch(e){notify(e.message)}};
useEffect(()=>{if(!pix?.installmentId||!token)return;let active=true;const timer=setInterval(async()=>{try{const status=await request(`/my/installments/${pix.installmentId}/payment-status`,'GET',undefined,token);if(active&&status.installmentStatus==='PAID'){setPix(null);refresh();notify('Pix confirmado pelo Mercado Pago! Parcela paga.')}}catch{}},5000);return()=>{active=false;clearInterval(timer)}},[pix?.installmentId,token]);
useEffect(()=>{if(!token)return;request('/me','GET',undefined,token).then(u=>{setUser(u);refresh(token,u.role)}).catch(()=>{sessionStorage.removeItem('gi-token');setToken('')})},[token]);
async function run(action,success){setLoading(true);try{await action();notify(success);await refresh()}catch(e){notify(e.message)}finally{setLoading(false)}}
async function signIn(e){e.preventDefault();setLoading(true);try{const r=await request('/login','POST',login);sessionStorage.setItem('gi-token',r.token);setToken(r.token);setUser(r.user);setMessage('');setPage('Início')}catch(e){notify(e.message)}finally{setLoading(false)}}
function logout(){sessionStorage.removeItem('gi-token');setToken('');setUser(null);setPage('Início');setMessage('');setLogin({cpf:'',password:''})}
function editClient(c){setEditingClient(c.id);setCf({...emptyClient,...c,name:c.user.name,cpf:c.user.cpf,birthDate:c.birthDate?.slice(0,10)||'',password:''});setPage('Clientes');window.scrollTo(0,0)}
function editProperty(p){setEditingProperty(p.id);setPf({...emptyProperty,...p});setPage('Imóveis');window.scrollTo(0,0)}
const menus=user?.role==='ADMIN'?[['Visão geral',LayoutDashboard],['Clientes',Users],['Imóveis',Building2],['Contratos',FileText],['Cobranças',CalendarClock],['Relatórios',ChartNoAxesCombined],['Comprovantes',Receipt]]:[['Início',LayoutDashboard],['Meus contratos',FileText],['Meu perfil',Users]];
const clientInstallments=mine.flatMap(c=>(c.installments||[]).map(i=>({i,c})));const unpaidClientInstallments=clientInstallments.filter(({i})=>i.status!=='PAID').sort((a,b)=>new Date(a.i.dueDate)-new Date(b.i.dueDate));const featuredBill=unpaidClientInstallments.find(({i})=>{const d=new Date(i.dueDate),n=new Date();return d.getUTCFullYear()===n.getFullYear()&&d.getUTCMonth()===n.getMonth()})||unpaidClientInstallments[0];const greetingHour=new Date().getHours();const greeting=greetingHour<12?'Bom dia':greetingHour<18?'Boa tarde':'Boa noite';const allInstallments=contracts.flatMap(c=>c.installments.map(i=>({...i,contract:c})));
const today=new Date();today.setHours(0,0,0,0);
const overdue=i=>i.status!=='PAID'&&new Date(i.dueDate)<today;
const sum=(list)=>list.reduce((a,i)=>a+i.amount,0);
function whatsappLink(i){const c=i.contract;const phone=String(c.client.phone||'').replace(/\D/g,'');if(phone.length<10)return null;const number=phone.startsWith('55')?phone:'55'+phone;const text=`Olá, ${c.client.user.name}! Aqui é da ALP Imobiliária. Lembrete da parcela ${i.number} referente ao imóvel ${c.property.reference}, no valor de ${money(i.amount)}, vencimento ${date(i.dueDate)}. Acesse https://gestao-imoveis-v2.vercel.app para pagar via Pix. Se já pagou, desconsidere. Obrigado!`;return `https://wa.me/${number}?text=${encodeURIComponent(text)}`}
function csvExport(clientId=null){const header=['Contrato','Cliente','Imóvel','Parcela','Vencimento','Valor (R$)','Status'];const rows=allInstallments.filter(i=>!clientId||i.contract.clientId===clientId).map(i=>[i.contract.id,i.contract.client.user.name,i.contract.property.reference,i.number,date(i.dueDate),(i.amount/100).toFixed(2).replace('.',','),overdue(i)?'Vencida':i.status]);const cell=v=>'"'+String(v??'').replace(/"/g,'""')+'"';const csv='\uFEFF'+[header,...rows].map(row=>row.map(cell).join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=clientId?'pagamentos-cliente.csv':'relatorio-financeiro.csv';a.click();URL.revokeObjectURL(url)}
const filtered=(arr,fn)=>arr.filter(x=>fn(x).toLowerCase().includes(search.toLowerCase()));
async function showPix(id){try{setPix({...await request(`/my/installments/${id}/pix`,'POST',{},token),installmentId:id})}catch(e){notify(e.message)}}
 function exportarRelatorioCSV(){
  const rows=mine.flatMap(c=>c.installments.map(i=>({c,i}))).sort((a,b)=>String(a.c.id).localeCompare(String(b.c.id))||a.i.number-b.i.number);
  const values=[['Contrato','Imóvel','Parcela','Status','Data da parcela'],...rows.map(({c,i})=>[`Contrato do imóvel: ${c.property.reference||'Não informado'}`,c.property.reference||'Não informado',`${i.number}/${c.installmentCount}`,i.status==='PAID'?'Pago':i.status==='PENDING_REVIEW'?'Em análise':overdue(i)?'Vencida':'Em aberto',date(i.dueDate)])];
  const csv='\uFEFF'+values.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(';')).join('\r\n');
  const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download='alp-relatorio-parcelas.csv';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
 }
   function baixarRelatorioPDF(){
    try{
     // PDF produzido no navegador, sem abrir impressão ou outra janela.
     const enc=new TextEncoder();const latin=t=>Array.from(String(t??''),ch=>{const n=ch.charCodeAt(0);return n<=255?n:({8211:150,8212:151,8216:145,8217:146,8220:147,8221:148,8226:149,8364:128}[n]||63)});
     const escape=t=>String(t??'').replace(/\\/g,'\\\\').replace(/\(/g,'\\(').replace(/\)/g,'\\)').replace(/[^\x20-\x7e\xA0-\xFF]/g,'?');
     const objects=[null];const add=v=>{objects.push(v);return objects.length-1};
     const font=add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>');
     const bold=add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>');
     const logoBytes=Uint8Array.from(atob(ALP_REPORT_LOGO.split(',')[1]),c=>c.charCodeAt(0));
     const logo=add({head:`<< /Type /XObject /Subtype /Image /Width 330 /Height 220 /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${logoBytes.length} >>`,bytes:logoBytes});
     const pages=[];let ops=[],y=0;
     const txt=(t,x,yy,size=10,isBold=false,color='0.12 0.18 0.29')=>{ops.push(`${color} rg BT /${isBold?'F2':'F1'} ${size} Tf 1 0 0 1 ${x} ${yy} Tm (${escape(t)}) Tj ET`)};
     const line=(x1,yy1,x2,yy2)=>ops.push(`0.85 0.88 0.92 RG 0.7 w ${x1} ${yy1} m ${x2} ${yy2} l S`);
     const rect=(x,yy,w,h,r='0.95 0.96 0.98')=>ops.push(`${r} rg ${x} ${yy} ${w} ${h} re f`);
     const newPage=()=>{ops=[];y=735;ops.push('q 92 0 0 61 44 748 cm /Logo Do Q');ops.push('Q');txt('A.L.P IMOBILIÁRIA',153,786,16,true);txt('RELATÓRIO DE PARCELAS',153,769,10,true,'0.35 0.40 0.49');line(44,737,551,737)};
     const finish=()=>{txt('A.L.P Imobiliária  |  Relatório informativo de parcelas',44,35,8,false,'0.4 0.45 0.53');const stream=ops.join('\n');const bytes=Uint8Array.from(latin(stream));const content=add({head:`<< /Length ${bytes.length} >>`,bytes});const page=add(`<< /Type /Page /Parent PARENT 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 ${font} 0 R /F2 ${bold} 0 R >> /XObject << /Logo ${logo} 0 R >> >> /Contents ${content} 0 R >>`);pages.push(page)};
     const ensure=h=>{if(y-h<62){finish();newPage()}};
     newPage();txt('Cliente',44,y,9,false,'0.4 0.45 0.53');txt(user.name||'Não informado',44,y-17,12,true);txt('Emitido em '+new Date().toLocaleDateString('pt-BR'),395,y-17,9);y-=56;
     const all=mine.flatMap(c=>(c.installments||[]));const paid=all.filter(i=>i.status==='PAID');const due=all.filter(i=>i.status!=='PAID');
     rect(44,y-52,507,65);txt('TOTAL DE PARCELAS',56,y-4,9,true);txt(String(all.length),56,y-27,16,true);txt('PAGAS',215,y-4,9,true);txt(String(paid.length),215,y-27,16,true);txt('EM ABERTO / PENDENTES',340,y-4,9,true);txt(String(due.length),340,y-27,16,true);y-=91;
     for(const c of mine){ensure(125);txt('Imóvel: '+String(c.property?.reference||'Não informado').slice(0,67),44,y,12,true);y-=17;txt(String(c.property?.address||'Endereço não informado').slice(0,90),44,y,9);y-=20;rect(44,y-8,507,26,'0.10 0.17 0.29');txt('PARCELA',54,y+1,9,true,'1 1 1');txt('VENCIMENTO',155,y+1,9,true,'1 1 1');txt('SITUAÇÃO',287,y+1,9,true,'1 1 1');txt('VALOR',466,y+1,9,true,'1 1 1');y-=30;
      for(const i of [...(c.installments||[])].sort((a,b)=>a.number-b.number)){
       if(y<78){finish();newPage();txt('Continuação: '+String(c.property?.reference||'Imóvel'),44,y,11,true);y-=23;rect(44,y-8,507,26,'0.10 0.17 0.29');txt('PARCELA',54,y+1,9,true,'1 1 1');txt('VENCIMENTO',155,y+1,9,true,'1 1 1');txt('SITUAÇÃO',287,y+1,9,true,'1 1 1');txt('VALOR',466,y+1,9,true,'1 1 1');y-=30}
       const status=i.status==='PAID'?'Paga':i.status==='PENDING_REVIEW'?'Em análise':overdue(i)?'Vencida':'Em aberto';
       txt(`${i.number}/${c.installmentCount}`,54,y,10);txt(date(i.dueDate),155,y,10);txt(status,287,y,10);txt(money(i.amount),460,y,10);line(44,y-9,551,y-9);y-=27;
      }
      ensure(55);txt('Total pago: '+money((c.installments||[]).filter(i=>i.status==='PAID').reduce((n,i)=>n+Number(i.amount||0),0)),54,y-3,10,true);txt('Saldo pendente: '+money((c.installments||[]).filter(i=>i.status!=='PAID').reduce((n,i)=>n+Number(i.amount||0),0)),287,y-3,10,true);y-=49;
     }
     ensure(58);line(44,y,551,y);y-=21;txt('TOTAL RECEBIDO: '+money(paid.reduce((n,i)=>n+Number(i.amount||0),0)),44,y,11,true);y-=20;txt('TOTAL PENDENTE: '+money(due.reduce((n,i)=>n+Number(i.amount||0),0)),44,y,11,true);finish();
     const pagesId=add('');const root=add(`<< /Type /Catalog /Pages ${pagesId} 0 R >>`);objects[pagesId]=`<< /Type /Pages /Kids [${pages.map(p=>p+' 0 R').join(' ')}] /Count ${pages.length} >>`;
     for(const p of pages)objects[p]=objects[p].replace('PARENT',String(pagesId));
     const chunks=[],offsets=[0];let position=0;const push=b=>{chunks.push(b);position+=b.length};const str=t=>Uint8Array.from(latin(t));push(str('%PDF-1.4\n%âãÏÓ\n'));
     for(let i=1;i<objects.length;i++){offsets[i]=position;push(str(`${i} 0 obj\n`));const obj=objects[i];if(typeof obj==='string')push(str(obj));else{push(str(obj.head+'\nstream\n'));push(obj.bytes);push(str('\nendstream'))}push(str('\nendobj\n'))}
     const xref=position;push(str(`xref\n0 ${objects.length}\n0000000000 65535 f \n`));for(let i=1;i<objects.length;i++)push(str(`${String(offsets[i]).padStart(10,'0')} 00000 n \n`));push(str(`trailer\n<< /Size ${objects.length} /Root ${root} 0 R >>\nstartxref\n${xref}\n%%EOF`));
     const blob=new Blob(chunks,{type:'application/pdf'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='ALP-relatorio-de-parcelas.pdf';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);
    }catch(e){notify('Não foi possível gerar o relatório: '+e.message)}
   }
async function baixarReciboPDF(i){try{const r=await fetch(API+`/installments/${encodeURIComponent(i.id)}/receipt-pdf`,{headers:{Authorization:`Bearer ${token}`}});if(!r.ok){const erro=await r.json().catch(()=>({}));throw Error(erro.error||`Não foi possível baixar o recibo (HTTP ${r.status})`)}const blob=await r.blob();if(!blob.type.includes('pdf'))throw Error('O servidor não retornou um PDF válido');const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`recibo-alp-parcela-${i.number}.pdf`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}catch(e){notify(e.message)}}
async function viewFile(id){try{const r=await fetch(API+`/receipts/${id}/file`,{headers:{Authorization:`Bearer ${token}`}});if(!r.ok)throw Error('Arquivo indisponível');const url=URL.createObjectURL(await r.blob());window.open(url,'_blank','noopener,noreferrer');setTimeout(()=>URL.revokeObjectURL(url),60000)}catch(e){notify(e.message)}}
if(!token)return <div className="login"><form className="panel loginform" onSubmit={signIn}><div className="logo">ALP</div><h1>ALP Imobiliária</h1><p>Entre com suas credenciais</p>{message&&<div className="notice">{message}</div>}{field('CPF',login.cpf,v=>{update(setLogin,'cpf',v);setMessage('')},'text',{required:true})}{field('Senha',login.password,v=>{update(setLogin,'password',v);setMessage('')},'password',{required:true})}<button disabled={loading}>Entrar</button></form></div>;
if(!user)return <div className="loading">Carregando...</div>;
if(user.mustChangePassword)return <div className="login"><form className="panel loginform" onSubmit={e=>{e.preventDefault();run(async()=>{await request('/me/password','PATCH',pw,token);setUser(u=>({...u,mustChangePassword:false}));setPw({currentPassword:'',newPassword:''})},'Senha alterada com sucesso')}}><div className="logo">ALP</div><h2>Primeiro acesso: altere sua senha</h2><p>Para sua segurança, a troca da senha provisória é obrigatória.</p>{message&&<div className="notice">{message}</div>}{field('Senha provisória',pw.currentPassword,v=>update(setPw,'currentPassword',v),'password',{required:true})}{field('Nova senha (mínimo 10 caracteres)',pw.newPassword,v=>update(setPw,'newPassword',v),'password',{required:true,minLength:10})}<button disabled={loading}>Alterar senha e continuar</button><button type="button" className="secondary" onClick={logout}>Sair</button></form></div>;
return <><style>{ALP_BILL_STYLES+ALP_HOME_STYLES+ALP_PROFILE_FIX_STYLES+ALP_RECEIPT_REPORT_STYLES+ALP_REPORT_RECEIPT_STYLES+ALP_ADMIN_STYLES}</style><div className={user.role==='ADMIN'?'shell alp-admin-shell':'shell alp-client-shell'}><aside><div className="logo">ALP</div><h2>ALP Imobiliária</h2><small>{user.role==='ADMIN'?'Painel administrativo':'Área do cliente'}</small><nav>{menus.map(([label,Icon])=><button key={label} className={page===label?'nav active':'nav'} onClick={()=>{setPage(label);setSelected(null);setSearch('');setMessage('');if(label==='Meus contratos'){setBillDetail(null);setShowInstallmentReport(false)}}}><Icon size={19}/>{label}</button>)}</nav><button className="exit" onClick={logout}><LogOut size={18}/> Sair</button></aside><main><div className="heading" style={user.role==='ADMIN'?undefined:{display:'none'}}><div><small>ALP IMOBILIÁRIA · PAINEL ADMINISTRATIVO</small><h1>{greeting}, {user.name.split(' ')[0]}! <span className="wave">✦</span></h1><p className="alp-admin-subtitle">Gerencie seu patrimônio com praticidade e segurança.</p></div><span className="tag"><ShieldCheck size={16}/> {user.role==='ADMIN'?'Administrador':'Cliente'}</span></div>{user.role!=='ADMIN'&&page!=='Início'&&<div className="alp-client-topbar"><button type="button" onClick={()=>{setPage('Início');setBillDetail(null);setShowInstallmentReport(false)}}>← Início</button><strong>ALP Imobiliária</strong><button type="button" onClick={logout}>Sair</button></div>}{message&&<div className="notice" role="status">{message}<button className="close" onClick={()=>setMessage('')}>×</button></div>}
{user.role!=='ADMIN'&&page==='Início'&&<section className="alp-home"><header className="alp-home-header"><div className="alp-home-brand"><span className="alp-home-brand-icon"><Building2 size={25}/></span><strong>ALP IMOBILIÁRIA</strong></div><button type="button" className="alp-home-profile" aria-label="Meu perfil" onClick={()=>setPage('Meu perfil')}><Users size={25}/></button><h1>{greeting}, {user.name.split(' ')[0]}!</h1></header><div className="alp-home-body"><article className="alp-home-invoice">{featuredBill?(()=>{const {i,c}=featuredBill;const pending=i.status==='PENDING_REVIEW';const month=new Date(i.dueDate).toLocaleDateString('pt-BR',{timeZone:'UTC',month:'long'});return <><div className="alp-home-invoice-title"><h2>Parcela de {month}</h2><span className="alp-home-mark">ALP</span></div><strong className="alp-home-price">{money(i.amount)}</strong><p>{overdue(i)?'Vencimento em':'Valor válido até'} {date(i.dueDate)}</p><small>{c.property.reference} · Parcela {i.number}/{c.installmentCount}</small><div className="alp-home-buttons"><button type="button" disabled={pending} onClick={()=>showPix(i.id)}>{pending?'Em análise':'Pagar'}</button><button type="button" className="alp-home-secondary" onClick={()=>{setShowInstallmentReport(false);setBillDetail(i.id);setPage('Meus contratos')}}>Ver detalhes</button></div></>})():<><div className="alp-home-invoice-title"><h2>Minhas Parcelas</h2><span className="alp-home-mark">ALP</span></div><p>{clientInstallments.length?'Nenhuma parcela em aberto.':'Nenhuma parcela disponível no momento.'}</p><div className="alp-home-buttons"><button type="button" className="alp-home-secondary" onClick={()=>{setBillDetail(null);setShowInstallmentReport(false);setBillTab('paid');setPage('Meus contratos')}}>Ver parcelas</button></div></>}</article><div className="alp-home-shortcuts"><button type="button" onClick={()=>{setBillDetail(null);setShowInstallmentReport(false);setBillTab('open');setPage('Meus contratos')}}><span><Receipt size={26}/></span><strong>Minhas<br/>Parcelas</strong></button><button type="button" onClick={baixarRelatorioPDF}><span><FileText size={26}/></span><strong>Baixar relatório de<br/>parcelas</strong></button><button type="button" onClick={()=>setPage('Meu perfil')}><span><Users size={26}/></span><strong>Meu<br/>perfil</strong></button></div></div></section>}
{page==='Visão geral'&&<><div className="hero"><div><span className="eyebrow">PAINEL DE CONTROLE</span><h2>Seu patrimônio, sob controle.</h2><p>Acompanhe clientes, imóveis, contratos e recebimentos em um só lugar.</p></div><div className="hero-symbol"><Building2 size={54}/></div></div><div className="stats alp-admin-overview-stats"><div className="panel"><span className="alp-admin-metric-icon"><Users size={22}/></span><small>Clientes</small><strong>{clients.length}</strong></div><div className="panel"><span className="alp-admin-metric-icon"><Building2 size={22}/></span><small>Imóveis</small><strong>{properties.length}</strong></div><div className="panel"><span className="alp-admin-metric-icon"><FileText size={22}/></span><small>Contratos</small><strong>{contracts.length}</strong></div><div className="panel"><span className="alp-admin-metric-icon"><Receipt size={22}/></span><small>Comprovantes pendentes</small><strong>{receipts.filter(r=>r.status==='PENDING').length}</strong></div></div><div className="panel"><h3>Resumo financeiro</h3><p>Total contratado: <b>{money(contracts.reduce((s,c)=>s+(c.propertyPrice||0),0))}</b></p><p>Parcelas pagas: <b>{contracts.reduce((s,c)=>s+c.installments.filter(i=>i.status==='PAID').length,0)}</b></p></div><div className="panel"><div className="section-head"><div><h3>Calendário de vencimentos</h3><p>Verde: em dia · Amarelo: a vencer · Vermelho: atrasado</p></div><input type="month" value={calendarMonth} onChange={e=>setCalendarMonth(e.target.value)}/></div><Calendar month={calendarMonth} installments={allInstallments}/></div></>}
{page==='Cobranças'&&<><div className="section-head"><div><h2>Central de cobranças</h2><p>Consulte vencimentos e envie lembretes personalizados pelo WhatsApp.</p></div></div><div className="stats"><div className="panel metric"><small>Em aberto</small><strong>{money(sum(allInstallments.filter(i=>i.status==='OPEN')))}</strong></div><div className="panel metric"><small>Vencidas</small><strong>{money(sum(allInstallments.filter(overdue)))}</strong></div><div className="panel metric"><small>Em análise</small><strong>{money(sum(allInstallments.filter(i=>i.status==='PENDING_REVIEW')))}</strong></div><div className="panel metric"><small>Recebido</small><strong>{money(sum(allInstallments.filter(i=>i.status==='PAID')))}</strong></div></div><SearchInput value={search} onChange={setSearch} placeholder="Buscar cliente, imóvel ou parcela"/><div className="panel tablewrap"><table><thead><tr><th>Cliente</th><th>Imóvel</th><th>Parcela</th><th>Vencimento</th><th>Valor</th><th>Situação</th><th>WhatsApp</th></tr></thead><tbody>{filtered(allInstallments,i=>`${i.contract.client.user.name} ${i.contract.property.reference} ${i.number}`).sort((a,b)=>new Date(a.dueDate)-new Date(b.dueDate)).map(i=><tr key={i.id}><td><b>{i.contract.client.user.name}</b><br/><small>{i.contract.client.phone||'Sem telefone'}</small></td><td>{i.contract.property.reference}</td><td>{i.number}/{i.contract.installmentCount}</td><td>{date(i.dueDate)}</td><td>{money(i.amount)}</td><td><Status value={overdue(i)?'Vencida':i.status}/></td><td>{i.status!=='PAID'&&whatsappLink(i)?<a className="wa-button" href={whatsappLink(i)} target="_blank" rel="noopener noreferrer"><MessageCircle size={16}/> Enviar lembrete</a>:i.status==='PAID'?'Quitada':'Cadastrar telefone'}</td></tr>)}</tbody></table>{allInstallments.length===0&&<p>Cadastre um contrato para visualizar as cobranças.</p>}</div><p className="hint">O botão abre o WhatsApp com a mensagem preenchida. O envio é feito por você. Para disparos automáticos é necessária uma conta WhatsApp Business Platform, autorização dos destinatários e modelos aprovados pela Meta.</p></>}
{page==='Relatórios'&&<><div className="section-head"><div><h2>Relatórios financeiros</h2><p>Visão consolidada dos recebimentos e parcelas por situação.</p></div><button onClick={csvExport}><Download size={17}/> Exportar CSV</button></div><div className="stats"><div className="panel metric"><small>Valor contratado</small><strong>{money(contracts.reduce((a,c)=>a+(c.propertyPrice||0),0))}</strong></div><div className="panel metric"><small>Total das parcelas</small><strong>{money(sum(allInstallments))}</strong></div><div className="panel metric"><small>Recebido</small><strong>{money(sum(allInstallments.filter(i=>i.status==='PAID')))}</strong></div><div className="panel metric"><small>Saldo pendente</small><strong>{money(sum(allInstallments.filter(i=>i.status!=='PAID')))}</strong></div></div><div className="panel"><h3>Distribuição financeira das parcelas</h3>{[['Recebido',sum(allInstallments.filter(i=>i.status==='PAID')),'paid'],['Em análise',sum(allInstallments.filter(i=>i.status==='PENDING_REVIEW')),'review'],['Em aberto / vencido',sum(allInstallments.filter(i=>!['PAID','PENDING_REVIEW'].includes(i.status))),'open']].map(([label,value,cls])=><div className="barrow" key={label}><div><span>{label}</span><b>{money(value)}</b></div><div className="bartrack"><div className={'barfill '+cls} style={{width:`${sum(allInstallments)?Math.max(0,value/sum(allInstallments)*100):0}%`}}/></div></div>)}</div><div className="panel"><h3>Resumo por imóvel</h3><div className="tablewrap"><table><thead><tr><th>Imóvel</th><th>Contratos</th><th>Previsto</th><th>Recebido</th><th>Em aberto</th></tr></thead><tbody>{properties.map(p=>{const cs=contracts.filter(c=>c.propertyId===p.id),ins=cs.flatMap(c=>c.installments);return <tr key={p.id}><td>{p.reference}</td><td>{cs.length}</td><td>{money(sum(ins))}</td><td>{money(sum(ins.filter(i=>i.status==='PAID')))}</td><td>{money(sum(ins.filter(i=>i.status!=='PAID')))}</td></tr>})}</tbody></table></div></div><div className="panel"><h3>Relatório de pagamentos por cliente</h3><div className="report-actions">{clients.map(c=><button className="small secondary" key={c.id} onClick={()=>csvExport(c.id)}><Download size={14}/> {c.user.name}</button>)}</div></div></>}
{page==='Clientes'&&<><h2>{editingClient?'Editar cliente':'Cadastrar cliente'}</h2><form className="panel formgrid" onSubmit={e=>{e.preventDefault();run(()=>request(editingClient?`/clients/${editingClient}`:'/clients',editingClient?'PUT':'POST',cf,token),editingClient?'Cliente atualizado':'Cliente cadastrado');setEditingClient(null);setCf(emptyClient)}}>{field('Nome completo',cf.name,v=>update(setCf,'name',v),'text',{required:true})}{field('CPF',cf.cpf,v=>update(setCf,'cpf',v),'text',{required:true})}{!editingClient&&field('Senha inicial (mín. 8 caracteres)',cf.password,v=>update(setCf,'password',v),'password',{required:true,minLength:8})}{field('RG',cf.rg,v=>update(setCf,'rg',v))}{field('Nascimento',cf.birthDate,v=>update(setCf,'birthDate',v),'date')}{field('Sexo',cf.sex,v=>update(setCf,'sex',v))}{field('Telefone',cf.phone,v=>update(setCf,'phone',v))}{field('E-mail',cf.email,v=>update(setCf,'email',v),'email')}{<label className="field"><span>Estado civil</span><select value={cf.maritalStatus||''} onChange={e=>update(setCf,'maritalStatus',e.target.value)}>{['','Solteiro(a)','Casado(a)','União estável','Divorciado(a)','Viúvo(a)'].map(v=><option key={v}>{v}</option>)}</select></label>}{['Casado(a)','União estável'].includes(cf.maritalStatus)&&<>{field('Nome do cônjuge',cf.spouseName,v=>update(setCf,'spouseName',v))}{field('CPF do cônjuge',cf.spouseCpf,v=>update(setCf,'spouseCpf',v))}</>}<div className="actions"><button disabled={loading}>{editingClient?'Salvar alterações':'Cadastrar cliente'}</button>{editingClient&&<button type="button" className="secondary" onClick={()=>{setEditingClient(null);setCf(emptyClient)}}>Cancelar</button>}</div></form><h2>Clientes cadastrados</h2><SearchInput value={search} onChange={setSearch}/><div className="panel tablewrap"><table><thead><tr><th>Nome</th><th>CPF</th><th>Telefone</th><th>Situação</th><th>Ações</th></tr></thead><tbody>{filtered(clients,c=>`${c.user.name} ${c.user.cpf} ${c.phone}`).map(c=><tr key={c.id}><td>{c.user.name}</td><td>{c.user.cpf}</td><td>{c.phone||'-'}</td><td><Status value={c.user.active?'Ativo':'Inativo'}/></td><td><button className="small" onClick={()=>editClient(c)}>Editar</button> <button className="small secondary" onClick={()=>run(()=>request(`/clients/${c.id}/status`,'PATCH',{active:!c.user.active},token),'Situação atualizada')}>{c.user.active?'Desativar':'Ativar'}</button> <button className="small danger" onClick={()=>{if(window.confirm('Excluir este cliente? Clientes com contratos não podem ser excluídos.'))run(()=>request(`/clients/${c.id}`,'DELETE',undefined,token),'Cliente excluído')}}>Excluir</button></td></tr>)}</tbody></table>{clients.length===0&&<p>Nenhum cliente cadastrado.</p>}</div></>}
{page==='Imóveis'&&<><h2>{editingProperty?'Editar imóvel':'Cadastrar imóvel'}</h2><form className="panel formgrid" onSubmit={e=>{e.preventDefault();run(()=>request(editingProperty?`/properties/${editingProperty}`:'/properties',editingProperty?'PUT':'POST',pf,token),editingProperty?'Imóvel atualizado':'Imóvel cadastrado');setEditingProperty(null);setPf(emptyProperty)}}>{field('Referência / identificação',pf.reference,v=>update(setPf,'reference',v),'text',{required:true})}{field('Endereço',pf.address,v=>update(setPf,'address',v),'text',{required:true})}<label className="field"><span>Estado (UF)</span><select value={pf.stateCode||''} onChange={e=>{const uf=e.target.value;setPf(p=>({...p,stateCode:uf,city:'',cityCode:''}))}}><option value="">Selecione</option>{ufs.map(u=><option key={u} value={u}>{u}</option>)}</select></label>{field('Cidade',pf.city,v=>update(setPf,'city',v))}{field('Código IBGE do município (opcional)',pf.cityCode,v=>update(setPf,'cityCode',v))}{field('Observações',pf.notes,v=>update(setPf,'notes',v))}<label className="field"><span>Financiado?</span><select value={String(pf.financed??'')} onChange={e=>update(setPf,'financed',e.target.value==='true')}><option value="false">Não</option><option value="true">Sim</option></select></label><div className="actions"><button disabled={loading}>{editingProperty?'Salvar alterações':'Cadastrar imóvel'}</button>{editingProperty&&<button type="button" className="secondary" onClick={()=>{setEditingProperty(null);setPf(emptyProperty)}}>Cancelar</button>}</div></form><h2>Imóveis cadastrados</h2><SearchInput value={search} onChange={setSearch}/><div className="panel tablewrap"><table><thead><tr><th>Referência</th><th>Endereço</th><th>Cidade / UF</th><th>Situação</th><th>Ações</th></tr></thead><tbody>{filtered(properties,p=>`${p.reference} ${p.address} ${p.city}`).map(p=><tr key={p.id}><td>{p.reference}</td><td>{p.address}</td><td>{p.city||'-'} / {p.stateCode||'-'}</td><td><Status value={p.active?'Ativo':'Inativo'}/></td><td><button className="small" onClick={()=>editProperty(p)}>Editar</button> <button className="small secondary" onClick={()=>run(()=>request(`/properties/${p.id}/status`,'PATCH',{active:!p.active},token),'Situação atualizada')}>{p.active?'Desativar':'Ativar'}</button> <button className="small secondary" onClick={()=>setModal({title:'Detalhes do imóvel',body:<div className="detailgrid">{Object.entries({Referência:p.reference,Endereço:p.address,Cidade:p.city,UF:p.stateCode,'Código IBGE':p.cityCode,Financiado:p.financed?'Sim':'Não',Situação:p.active?'Ativo':'Inativo',Observações:p.notes}).map(([k,v])=><div key={k}><small>{k}</small><strong>{v||'—'}</strong></div>)}</div>})}>Visualizar</button> <button className="small danger" onClick={()=>{if(window.confirm('Excluir este imóvel? Imóveis com contratos não podem ser excluídos.'))run(()=>request(`/properties/${p.id}`,'DELETE',undefined,token),'Imóvel excluído')}}>Excluir</button></td></tr>)}</tbody></table>{properties.length===0&&<p>Nenhum imóvel cadastrado.</p>}</div></>}
{page==='Contratos'&&<><h2>{editingContract?'Editar contrato':'Criar contrato e parcelas'}</h2><form className="panel formgrid" onSubmit={e=>{e.preventDefault();run(()=>request(editingContract?`/contracts/${editingContract}`:'/contracts',editingContract?'PATCH':'POST',{...kf,propertyPrice:cents(kf.propertyPrice),financedAmount:cents(kf.financedAmount),installmentCount:Number(kf.installmentCount),monthlyRate:Number(kf.monthlyRate)},token),editingContract?'Contrato atualizado':'Contrato criado com sucesso');setEditingContract(null);setKf(emptyContract)}}><label className="field"><span>Cliente</span><select required value={kf.clientId} onChange={e=>update(setKf,'clientId',e.target.value)}><option value="">Selecione</option>{clients.filter(c=>c.user.active).map(c=><option key={c.id} value={c.id}>{c.user.name} — {c.user.cpf}</option>)}</select></label><label className="field"><span>Imóvel</span><select required value={kf.propertyId} onChange={e=>update(setKf,'propertyId',e.target.value)}><option value="">Selecione</option>{properties.filter(p=>p.active).map(p=><option key={p.id} value={p.id}>{p.reference} — {p.address}</option>)}</select></label>{field('Valor total do imóvel (R$)',kf.propertyPrice,v=>update(setKf,'propertyPrice',v),'number',{required:true,min:0.01,step:0.01})}{field('Valor financiado (R$)',kf.financedAmount,v=>update(setKf,'financedAmount',v),'number',{required:true,min:0,step:0.01})}<div className="field"><span>Entrada calculada</span><b className="computed">{money(Math.max(0,cents(kf.propertyPrice)-cents(kf.financedAmount)))}</b></div><label className="field"><span>Modalidade de juros</span><select value={kf.interestType} onChange={e=>update(setKf,'interestType',e.target.value)}><option value="NONE">Sem juros</option><option value="SIMPLE">Juros simples</option><option value="PRICE">Tabela Price</option></select></label>{kf.interestType!=='NONE'&&field('Taxa mensal (%)',kf.monthlyRate,v=>update(setKf,'monthlyRate',v),'number',{min:0,max:100,step:0.0001})}{field('Quantidade de parcelas',kf.installmentCount,v=>update(setKf,'installmentCount',v),'number',{required:true,min:1,max:600})}{field('Vencimento da primeira parcela',kf.startDate,v=>update(setKf,'startDate',v),'date',{required:true})}<div className="actions"><button disabled={loading}>{editingContract?'Salvar contrato':'Criar contrato'}</button>{editingContract&&<button type="button" className="secondary" onClick={()=>{setEditingContract(null);setKf(emptyContract)}}>Cancelar</button>}</div></form><h2>Contratos cadastrados</h2><SearchInput value={search} onChange={setSearch} placeholder="Pesquisar cliente, CPF ou imóvel"/><div className="panel tablewrap"><table><thead><tr><th>Contrato</th><th>Cliente</th><th>Imóvel</th><th>Valor total</th><th>Entrada</th><th>Financiado</th><th>Parcelas</th><th>Juros</th><th>Início</th><th>Situação</th><th>Ações</th></tr></thead><tbody>{filtered(contracts,c=>`${c.id} ${c.client.user.name} ${c.client.user.cpf} ${c.property.reference} ${c.property.address}`).map(c=><tr key={c.id}><td title={c.id}>{c.id.slice(0,8)}</td><td>{c.client.user.name}</td><td>{c.property.reference}</td><td>{money(c.propertyPrice)}</td><td>{money(c.downPayment)}</td><td>{money(c.financedAmount)}</td><td>{c.installmentCount}</td><td>{c.interestType==='NONE'?'Sem juros':c.interestType==='PRICE'?'Price':'Simples'} {c.interestType!=='NONE'&&`(${c.monthlyRate}% a.m.)`}</td><td>{date(c.startDate)}</td><td><Status value={c.installments.every(i=>i.status==='PAID')?'Quitado':'Em andamento'}/></td><td><button className="small" onClick={()=>setModal({title:`Parcelas — ${c.client.user.name}`,body:<Installments contract={c} onFile={viewFile}/>})}>Ver parcelas</button> <button className="small secondary" onClick={()=>{setEditingContract(c.id);setKf({clientId:c.clientId,propertyId:c.propertyId,propertyPrice:String((c.propertyPrice||0)/100),financedAmount:String((c.financedAmount||0)/100),installmentCount:String(c.installmentCount),startDate:c.startDate.slice(0,10),interestType:c.interestType,monthlyRate:String(c.monthlyRate||0)});window.scrollTo(0,0)}}>Editar</button> <button className="small danger" onClick={()=>{if(window.confirm('Excluir contrato? Somente contratos sem movimentação financeira podem ser excluídos.'))run(()=>request(`/contracts/${c.id}`,'DELETE',undefined,token),'Contrato excluído')}}>Excluir</button></td></tr>)}</tbody></table>{contracts.length===0&&<p>Nenhum contrato cadastrado.</p>}</div></>}
{page==='Comprovantes'&&<><h2>Comprovantes enviados</h2><SearchInput value={search} onChange={setSearch}/><div className="panel tablewrap"><table><thead><tr><th>Cliente</th><th>Imóvel</th><th>Parcela</th><th>Arquivo</th><th>Data</th><th>Situação</th><th>Ações</th></tr></thead><tbody>{filtered(receipts,r=>`${r.originalName} ${r.installment.contract.client.user.name} ${r.installment.contract.property.reference}`).map(r=><tr key={r.id}><td>{r.installment.contract.client.user.name}</td><td>{r.installment.contract.property.reference}</td><td>{r.installment.number}</td><td><button className="link" onClick={()=>viewFile(r.id)}>{r.originalName}</button></td><td>{date(r.createdAt)}</td><td><Status value={r.status}/></td><td>{r.status==='PENDING'&&<><button className="small" onClick={()=>run(()=>request(`/receipts/${r.id}`,'PATCH',{status:'APPROVED'},token),'Comprovante aprovado')}>Aprovar</button> <button className="small danger" onClick={()=>run(()=>request(`/receipts/${r.id}`,'PATCH',{status:'REJECTED',note:prompt('Motivo da rejeição:')||''},token),'Comprovante rejeitado')}>Rejeitar</button></>} <button className="small danger" onClick={()=>{if(window.confirm('Excluir este comprovante? Comprovantes aprovados não podem ser excluídos.'))run(()=>request(`/receipts/${r.id}`,'DELETE',undefined,token),'Comprovante excluído')}}>Excluir</button></td></tr>)}</tbody></table>{receipts.length===0&&<p>Nenhum comprovante enviado.</p>}</div></>}
{page==='Meus contratos'&&<section className="alp-bills">{showInstallmentReport?<div className="alp-report"><header className="alp-detail-header"><button type="button" className="alp-back" onClick={()=>setShowInstallmentReport(false)} aria-label="Voltar às faturas">←</button><strong>Relatório de parcelas</strong><span/></header><div id="alp-report-print" className="alp-report-content alp-doc"><header className="alp-doc-header"><div><h2>Relatório de Parcelas</h2><small>Emitido em {new Date().toLocaleDateString('pt-BR')}</small></div><img className="alp-doc-logo" src={ALP_REPORT_LOGO} alt="Logomarca A.L.P Imobiliária"/></header><div className="alp-doc-fields"><div><small>Nome do cliente</small><strong>{user.name}</strong></div><div><small>CPF do cliente</small><strong>{user.cpf||'Não informado'}</strong></div><div><small>Quantidade de contratos</small><strong>{mine.length}</strong></div><div><small>Total de parcelas</small><strong>{clientInstallments.length}</strong></div></div><div className="alp-doc-overview"><div><small>Parcelas pagas</small><strong>{clientInstallments.filter(({i})=>i.status==='PAID').length}</strong></div><div><small>Parcelas pendentes</small><strong>{clientInstallments.filter(({i})=>i.status!=='PAID').length}</strong></div><div><small>Total recebido</small><strong>{money(clientInstallments.filter(({i})=>i.status==='PAID').reduce((n,{i})=>n+i.amount,0))}</strong></div></div>{mine.map((c,index)=><section className="alp-doc-section" key={c.id}><h3>Detalhamento das parcelas · Contrato {index+1}</h3><div className="alp-doc-fields alp-doc-contract-fields"><div><small>Imóvel</small><strong>{c.property.reference||'Não informado'}</strong></div><div><small>Endereço</small><strong>{c.property.address||'Não informado'}</strong></div></div><table className="alp-doc-table"><thead><tr><th>Descrição</th><th>Vencimento</th><th>Situação</th><th>Valor</th></tr></thead><tbody>{[...(c.installments||[])].sort((a,b)=>a.number-b.number).map(i=><tr key={i.id}><td>Parcela {i.number}/{c.installmentCount}</td><td>{date(i.dueDate)}</td><td>{i.status==='PAID'?'Paga':i.status==='PENDING_REVIEW'?'Em análise':overdue(i)?'Vencida':'Em aberto'}</td><td>{money(i.amount)}</td></tr>)}</tbody></table><div className="alp-doc-total"><small>Recebido neste contrato</small><strong>{money(c.installments.filter(i=>i.status==='PAID').reduce((n,i)=>n+i.amount,0))}</strong></div><div className="alp-doc-total"><small>Saldo pendente</small><strong>{money(c.installments.filter(i=>i.status!=='PAID').reduce((n,i)=>n+i.amount,0))}</strong></div></section>)}{mine.length===0&&<p>Nenhum contrato encontrado.</p>}<p className="alp-doc-note">A data da parcela corresponde ao vencimento contratual. As situações refletem os registros do sistema. Este relatório é informativo e não substitui os comprovantes individuais de pagamento.</p><footer className="alp-doc-footer"><strong>A.L.P Imobiliária</strong><small>Relatório de parcelas do cliente.</small></footer></div><div className="alp-report-actions"><button type="button" onClick={baixarRelatorioPDF}><Download size={17}/> Salvar em PDF</button><button type="button" className="secondary" onClick={exportarRelatorioCSV}><Download size={17}/> Baixar planilha CSV</button><button type="button" className="alp-report-close" onClick={()=>setShowInstallmentReport(false)}>Fechar relatório</button></div></div>:billDetail?(()=>{const found=mine.flatMap(c=>c.installments.map(i=>({i,c}))).find(x=>x.i.id===billDetail);if(!found)return <button onClick={()=>setBillDetail(null)}>Voltar</button>;const {i,c}=found;const paid=i.status==='PAID';const pending=i.status==='PENDING_REVIEW';return <div className="alp-detail"><header className="alp-detail-header"><button type="button" className="alp-back" aria-label="Voltar às faturas" onClick={()=>setBillDetail(null)}>←</button><strong>Detalhes da parcela</strong><span/></header>{paid&&<div className="alp-info">● &nbsp; Parcela paga{ i.paidAt?` no dia ${date(i.paidAt)}`:''}</div>}<div className="alp-detail-main"><h2>{c.property.reference||'Parcela do imóvel'}</h2><p className="alp-muted">{c.property.address}</p><p className="alp-muted">Vence em {new Date(i.dueDate).toLocaleDateString('pt-BR',{timeZone:'UTC',day:'2-digit',month:'long',year:'numeric'})}</p>{!paid&&<span className={'alp-status '+(pending?'alp-pending':'alp-upcoming')}>{pending?'Em análise':overdue(i)?'Vencida':'A vencer'}</span>}<div className="alp-total"><span>{paid?'Total pago':'Total a pagar'}</span><strong>{money(i.amount)}</strong></div>{!paid&&!pending&&<div className="alp-info">● &nbsp; {overdue(i)?'Esta parcela está vencida. Consulte o valor atualizado antes de pagar.':`Pague até ${date(i.dueDate)} para evitar juros e multa por atraso.`}</div>}{pending&&<div className="alp-info">● &nbsp; Seu comprovante está aguardando análise.</div>}{paid&&<div className="alp-items"><h3>Detalhamento do pagamento</h3><div><span>Parcela</span><span>{i.number} de {c.installmentCount}</span></div><div><span>Valor da parcela</span><span>{money(i.amount)}</span></div><p>{c.property.reference} · {c.property.address}</p><div className="alp-items-total"><b>Valor total</b><b>{money(i.amount)}</b></div></div>}</div><footer className="alp-detail-footer">{paid?<button type="button" onClick={()=>baixarReciboPDF(i)}>Baixar comprovante</button>:!pending?<button type="button" onClick={()=>showPix(i.id)}>Pagar</button>:<button type="button" disabled>Em análise</button>}</footer></div>})():<><header className="alp-list-header"><h2>Minhas Parcelas</h2><p>Acompanhe as parcelas dos seus contratos</p><button type="button" className="alp-report-open" onClick={baixarRelatorioPDF}><FileText size={17}/> Baixar relatório de parcelas</button></header><div className="alp-tabs" role="tablist"><button type="button" role="tab" aria-selected={billTab==='open'} className={billTab==='open'?'active':''} onClick={()=>setBillTab('open')}>Em aberto</button><button type="button" role="tab" aria-selected={billTab==='paid'} className={billTab==='paid'?'active':''} onClick={()=>setBillTab('paid')}>Pagas</button></div>{(()=>{const list=mine.flatMap(c=>c.installments.map(i=>({i,c}))).filter(({i})=>billTab==='paid'?i.status==='PAID':i.status!=='PAID').sort((a,b)=>new Date(b.i.dueDate)-new Date(a.i.dueDate));const groups={};for(const item of list){const key=new Date(item.i.dueDate).toLocaleDateString('pt-BR',{timeZone:'UTC',month:'long',year:'numeric'});(groups[key]??=[]).push(item)}return list.length===0?<p className="alp-empty">{billTab==='paid'?'Nenhuma parcela paga ainda.':'Nenhuma parcela em aberto.'}</p>:Object.entries(groups).map(([month,items])=><div className="alp-month" key={month}><h3>{month.charAt(0).toUpperCase()+month.slice(1)}</h3>{items.map(({i,c})=><article className="alp-bill-row" key={i.id}><h4>{c.property.reference||'Parcela do imóvel'}</h4><p>{c.property.address}</p><p>{date(i.dueDate)}</p><span className={'alp-status '+(i.status==='PAID'?'alp-paid':i.status==='PENDING_REVIEW'?'alp-pending':overdue(i)?'alp-overdue':'alp-upcoming')}>{i.status==='PAID'?'Paga':i.status==='PENDING_REVIEW'?'Em análise':overdue(i)?'Vencida':'A vencer'}</span><div className="alp-bill-bottom"><strong>{money(i.amount)}</strong><button type="button" onClick={()=>setBillDetail(i.id)}>Ver detalhes <span aria-hidden="true">→</span></button></div></article>)}</div>)})()}</>}</section>}
{page==='Meu perfil'&&<div className="panel profile"><h2>Meu perfil</h2><p>O CPF permanece como seu login e não pode ser alterado aqui.</p>{!profile?<button onClick={()=>request('/me/profile','GET',undefined,token).then(setProfile).catch(e=>notify(e.message))}>Carregar meus dados</button>:<form className="formgrid" onSubmit={e=>{e.preventDefault();run(()=>request('/me/profile','PATCH',profile,token),'Perfil atualizado')}}>{field('Nome',profile.name,v=>update(setProfile,'name',v),'text',{required:true})}{field('CPF (login)',profile.cpf,()=>{},'text',{disabled:true})}{field('Nascimento',profile.birthDate?.slice(0,10)||'',v=>update(setProfile,'birthDate',v),'date')}{field('E-mail',profile.email,v=>update(setProfile,'email',v),'email')}<div className="actions"><button>Salvar perfil</button></div></form>}<h3>Alterar senha</h3><form className="formgrid" onSubmit={e=>{e.preventDefault();run(async()=>{await request('/me/password','PATCH',pw,token);setPw({currentPassword:'',newPassword:''})},'Senha alterada')}}>{field('Senha atual',pw.currentPassword,v=>update(setPw,'currentPassword',v),'password',{required:true})}{field('Nova senha (mínimo 10 caracteres)',pw.newPassword,v=>update(setPw,'newPassword',v),'password',{required:true,minLength:10})}<div className="actions"><button>Alterar senha</button></div></form></div>}
{pix&&<Modal title="Pagamento Pix — Mercado Pago" onClose={()=>{setPix(null);refresh()}}><div className="pixpanel"><h2>{money(pix.amount)}</h2>{pix.qrCode&&<img src={pix.qrCode} alt="QR Code Pix" width="260" height="260"/>}<p><b>Aguardando confirmação do pagamento</b></p><p>{pix.notice}</p><textarea readOnly rows={4} value={pix.payload||''}/><div className="actions"><button onClick={()=>navigator.clipboard.writeText(pix.payload||'')}>Copiar Pix</button><button className="secondary" onClick={async()=>{try{const s=await request(`/my/installments/${pix.installmentId}/payment-status`,'GET',undefined,token);if(s.installmentStatus==='PAID'){setPix(null);await refresh();notify('Pagamento confirmado!')}else notify('Ainda aguardando confirmação bancária')}catch(e){notify(e.message)}}}>Verificar pagamento</button></div></div></Modal>}
{modal&&<Modal title={modal.title} onClose={()=>setModal(null)}>{modal.body}</Modal>}
</main></div></>}
function Modal({title,children,onClose}){useEffect(()=>{const key=e=>{if(e.key==='Escape')onClose()};document.addEventListener('keydown',key);return()=>document.removeEventListener('keydown',key)},[onClose]);return <div className="modalback" role="presentation" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><div className="modalbox" role="dialog" aria-modal="true" aria-label={title}><div className="modalhead"><h2>{title}</h2><button className="secondary" onClick={onClose} aria-label="Fechar">✕</button></div>{children}<div className="modalfooter"><button className="secondary" onClick={onClose}>Fechar</button></div></div></div>}
function Calendar({month,installments}){const [year,m]=month.split('-').map(Number);const first=new Date(year,m-1,1),count=new Date(year,m,0).getDate(),offset=first.getDay();const days=Array.from({length:offset+count},(_,j)=>j-offset+1);return <div className="calendar"><div className="weekdays">{['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map(d=><b key={d}>{d}</b>)}</div><div className="calgrid">{days.map((d,k)=>{if(d<1)return <div key={k}/>;const items=installments.filter(i=>{const dt=new Date(i.dueDate);return dt.getUTCFullYear()===year&&dt.getUTCMonth()+1===m&&dt.getUTCDate()===d});return <div key={k} className="calday"><strong>{d}</strong>{items.slice(0,4).map(i=><span key={i.id} title={`${i.contract.client.user.name} — ${money(i.amount)}`} className={'calitem '+(i.status==='PAID'?'paid':new Date(i.dueDate)<new Date()?'late':'soon')}>{i.contract.client.user.name.split(' ')[0]} · {money(i.amount)}</span>)}{items.length>4&&<small>+{items.length-4} parcelas</small>}</div>})}</div></div>}
function SearchInput({value,onChange,placeholder='Pesquisar registros'}){return <div className="search"><Search size={18}/><input value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder}/></div>}
function Status({value}){const green=['Ativo','Quitado','PAID','APPROVED'].includes(value),red=['Inativo','REJECTED','Vencida'].includes(value);return <span className={'status '+(green?'green':red?'red':'amber')}>{({Vencida:'Vencida',OPEN:'Em aberto',PAID:'Pago',PENDING_REVIEW:'Em análise',PENDING:'Pendente',APPROVED:'Aprovado',REJECTED:'Rejeitado'})[value]||value}</span>}
function Installments({contract,onFile}){return <div className="panel"><h3>Parcelas — {contract.client.user.name} / {contract.property.reference}</h3><div className="tablewrap"><table><thead><tr><th>Nº</th><th>Vencimento</th><th>Valor</th><th>Situação</th><th>Comprovantes</th></tr></thead><tbody>{contract.installments.map(i=><tr key={i.id}><td>{i.number}/{contract.installmentCount}</td><td>{date(i.dueDate)}</td><td>{money(i.amount)}</td><td><Status value={i.status}/></td><td>{i.receipts.length?i.receipts.map(r=><button key={r.id} className="link" onClick={()=>onFile(r.id)}>{r.originalName}</button>):'—'}</td></tr>)}</tbody></table></div></div>}
const ufs=['AC','AL','AP','AM','BA','CE','DF','ES','GO','MA','MT','MS','MG','PA','PB','PR','PE','PI','RJ','RN','RS','RO','RR','SC','SP','SE','TO'];

